// Social Media Post Validator - Starter code with bug

// Environment configuration
const env = {
    config: {
        validateNoDerivedContentInEffects: true,
        validateNoStateUpdatesInEffects: true,
        validateNoJSXInTryStatements: true,
        validateStaticComponents: true
    },
    enableValidations: true,
    outputMode: 'publish', // Can be 'lint' or 'publish'
    logErrors: (errors) => {
        if (errors && errors.length > 0) {
            console.log('Validation errors:', errors);
        }
    }
};

// Mock validation functions (simplified for challenge)
function validateNoDerivedContentInEffects(hir) {
    return ['Error: Derived content in effect detected'];
}

function validateNoStateUpdatesInEffects(hir, env) {
    return ['Error: State update in effect detected'];
}

function validateNoJSXInTryStatement(hir) {
    return ['Error: JSX in try statement detected'];
}

function validateStaticComponents(hir) {
    return ['Error: Static component validation failed'];
}

// Main validation pipeline function (with bug)
function runWithEnvironment(env, hir) {
    // Run validations based on config
    if (env.config.validateNoDerivedContentInEffects) {
        env.logErrors(validateNoDerivedContentInEffects(hir));
    }

    if (env.config.validateNoStateUpdatesInEffects) {
        env.logErrors(validateNoStateUpdatesInEffects(hir, env));
    }

    if (env.config.validateNoJSXInTryStatements) {
        env.logErrors(validateNoJSXInTryStatement(hir));
    }

    // Additional validation
    if (env.enableValidations && env.config.validateStaticComponents) {
        env.logErrors(validateStaticComponents(hir));
    }

    return { value: hir };
}

// Example usage
const mockHIR = {};
console.log('Running validation in publish mode...');
const result = runWithEnvironment(env, mockHIR);
console.log('Validation result:', result);

// TODO: Fix the bug by adding env.outputMode === 'lint' checks to the validation conditions above
// The validations should only run when outputMode is 'lint', not in 'publish' mode

