// Test cases for the Social Media Post Validator

import { runWithEnvironment } from './server.js';

// Mock HIR object
const mockHIR = {};

// Test 1: Validation should NOT run in publish mode
console.log('Test 1: Publish mode (validations should not run)');
const envPublish = {
    config: {
        validateNoDerivedContentInEffects: true,
        validateNoStateUpdatesInEffects: true,
        validateNoJSXInTryStatements: true,
        validateStaticComponents: true
    },
    enableValidations: true,
    outputMode: 'publish',
    logErrors: (errors) => {
        if (errors && errors.length > 0) {
            throw new Error(`Validations ran in publish mode: ${errors}`);
        }
    }
};

try {
    const result1 = runWithEnvironment(envPublish, mockHIR);
    console.log('✓ Test 1 passed: No validations ran in publish mode');
} catch (error) {
    console.error('✗ Test 1 failed:', error.message);
    process.exit(1);
}

// Test 2: Validation SHOULD run in lint mode
console.log('\nTest 2: Lint mode (validations should run)');
let validationCount = 0;
const envLint = {
    config: {
        validateNoDerivedContentInEffects: true,
        validateNoStateUpdatesInEffects: true,
        validateNoJSXInTryStatements: true,
        validateStaticComponents: true
    },
    enableValidations: true,
    outputMode: 'lint',
    logErrors: (errors) => {
        if (errors && errors.length > 0) {
            validationCount++;
        }
    }
};

try {
    const result2 = runWithEnvironment(envLint, mockHIR);
    if (validationCount === 4) {
        console.log('✓ Test 2 passed: All 4 validations ran in lint mode');
    } else {
        throw new Error(`Expected 4 validations, but ran ${validationCount}`);
    }
} catch (error) {
    console.error('✗ Test 2 failed:', error.message);
    process.exit(1);
}

// Test 3: Validation with specific config disabled
console.log('\nTest 3: Lint mode with some validations disabled');
validationCount = 0;
const envPartial = {
    config: {
        validateNoDerivedContentInEffects: false,
        validateNoStateUpdatesInEffects: true,
        validateNoJSXInTryStatements: false,
        validateStaticComponents: true
    },
    enableValidations: true,
    outputMode: 'lint',
    logErrors: (errors) => {
        if (errors && errors.length > 0) {
            validationCount++;
        }
    }
};

try {
    const result3 = runWithEnvironment(envPartial, mockHIR);
    if (validationCount === 2) {
        console.log('✓ Test 3 passed: Only enabled validations ran');
    } else {
        throw new Error(`Expected 2 validations, but ran ${validationCount}`);
    }
} catch (error) {
    console.error('✗ Test 3 failed:', error.message);
    process.exit(1);
}

console.log('\n✅ All tests passed!');
